const rows = function (name) {
  try { return $(name).all().map(function (i) { return i.json; }).filter(function (r) { return r && Object.keys(r).length > 0 && !r.error; }); } catch (e) { return []; }
};
const req = $('Normalize Request').first().json;
const P = {};
rows('Read Parameters').forEach(function (r) { const v = r.value; P[r.key] = (v !== '' && v !== null && v !== undefined && !isNaN(Number(v))) ? Number(v) : v; });
const deals = rows('Read Deals');
const inv = rows('Read Investments');
const cps = rows('Read Counterparties');
const dealers = rows('Read Dealers');
const pos = rows('Read Positions');
const rl = rows('Read Restricted List').filter(function (r) { return r.isin; });
const num = function (x) { const n = Number(x); return isNaN(n) ? 0 : n; };
const r2 = function (x) { return Math.round(x * 100) / 100; };
const cpMap = {}; cps.forEach(function (c) { cpMap[c.counterparty] = c; });
const dlMap = {}; dealers.forEach(function (d) { dlMap[d.dealer_id] = d; });
const hm = function (t) { if (!t) return null; const p = String(t).split(':'); return num(p[0]) * 60 + num(p[1]); };
const ts = function (d, t) { if (!d || !t) return null; const dp = String(d).split('-'); const tp = String(t).split(':'); return Date.UTC(num(dp[0]), num(dp[1]) - 1, num(dp[2]), num(tp[0]), num(tp[1])); };
const periodTo = String(P.audit_period_to || '');
const mat = num(P.materiality_cr) || 5;

const CAT = [
 ['TR-01','Unconfirmed / unmatched deals','Back Office - Deal Confirmation','RBI','RBI Master Direction - Risk Management and Inter-Bank Dealings, 2016 (independent back-office confirmation); FEDAI Rules; CCIL trade matching','SA 505 External Confirmations; SA 330 Responses to Assessed Risks','High','Obtain and match confirmations for all outstanding deals; escalate unconfirmed deals daily to Mid Office and CRO.','deals'],
 ['TR-02','Delayed deal confirmation','Back Office - Deal Confirmation','RBI','RBI MD - Risk Management and Inter-Bank Dealings, 2016; Back-office SOP (confirmation SLA)','SA 330; SA 315 (Revised) - Internal Control','Medium','Enforce confirmation SLA; system alert for deals not confirmed within SLA.','deals'],
 ['TR-03','Segregation of duties - dealer confirming own deal','Front / Mid / Back Office Segregation','RBI','RBI guidelines on internal control in treasury (functional separation of front, mid and back office)','SA 315 (Revised); SA 265 Communicating Deficiencies in Internal Control; SA 240 Fraud','High','Restrict confirmation rights in the treasury system to back-office user IDs; review the user access matrix.','deals'],
 ['TR-04','Off-market rate deals','Dealing Room - Rate Reasonability','RBI / FEMA','RBI MD - Risk Management and Inter-Bank Dealings, 2016 (no off-market rate deals); FEDAI Code of Conduct; FBIL/FIMMDA benchmarks','SA 240 Fraud in an Audit; SA 520 Analytical Procedures','High','Mid office to rate-scan every deal against a market snapshot; obtain dealer justification and escalate.','deals'],
 ['TR-05','Dealing outside hours / unrecorded lines','Dealing Room Controls','RBI','RBI MD - Risk Management and Inter-Bank Dealings; Treasury Dealing Policy (deals only on recorded lines from dealing room)','SA 315 (Revised); SA 330','Medium','Prohibit after-hours deals without prior written approval; ensure all deals are on voice-recorded lines or electronic platforms.','deals'],
 ['TR-06','Counterparty exposure limit breach','Credit Risk - Counterparty Limits','RBI','RBI Master Circular - Exposure Norms; RBI Large Exposures Framework; Board-approved counterparty limits','SA 250 Consideration of Laws and Regulations; SA 330','High','Implement a hard pre-deal limit check in the treasury system; report breaches to the Risk Management Committee for ratification.','counterparties'],
 ['TR-07','Dealer per-deal limit breach','Delegation of Powers','RBI','Board-approved Treasury Policy / dealer limits under RBI MD - Risk Management and Inter-Bank Dealings','SA 315 (Revised); SA 265','Medium','Configure dealer-wise deal size limits in the system; obtain post-facto approval from the competent authority.','deals'],
 ['TR-08','Stop-loss limit breach','Market Risk - Stop-loss','RBI','RBI MD - Risk Management and Inter-Bank Dealings (stop-loss limits); Board Market Risk Policy','SA 315 (Revised); SA 540 (Revised)','High','Mid office to monitor stop-loss in real time; suspend dealing authority on breach until ALCO approval.','dealers'],
 ['TR-09','Net Overnight Open Position (NOOP) breach','Forex Risk - Open Position','RBI / FEMA','RBI MD - Risk Management and Inter-Bank Dealings, 2016 (Board-approved NOOP / AGL); FEMA 1999','SA 250; SA 330','High','Square off the excess; report to ALCO and RBI as required; strengthen intraday NOOP monitoring.','positions'],
 ['TR-10','Call money prudential limit breach','Money Market - Call / Notice','RBI','RBI Call, Notice and Term Money Markets Directions, 2021 - prudential limits linked to capital funds','SA 250; SA 330','High','Monitor call borrowing/lending against capital-fund-based limits in real time; plan liquidity via TREPS / term money.','positions'],
 ['TR-11','Settlement failure / SGL bounce','Settlement - SGL / CSGL','RBI','RBI instructions on SGL bouncing (penalties; repeated bounces can lead to suspension of SGL facility); CCIL settlement rules','SA 330; SA 505','High','Investigate root cause; ensure adequate SGL / fund balance before settlement; report the bounce as required.','deals'],
 ['TR-12','HTM sales - approval and disclosure','Investment Portfolio - HTM','RBI','RBI (Classification, Valuation and Operation of Investment Portfolio of Commercial Banks) Directions, 2023 - sales out of HTM','SA 250; SA 450 Evaluation of Misstatements','High','Obtain Board approval for HTM sales; disclose HTM sales above threshold in Notes to Accounts.','investments'],
 ['TR-13','Fair value loss not recognised','Investment Portfolio - Valuation','RBI','RBI Investment Portfolio Directions, 2023 (AFS through AFS-Reserve; FVTPL / HFT through P and L)','SA 540 (Revised) Auditing Accounting Estimates; SA 450','High','Recognise the unrecognised fair value loss; use FBIL / exchange prices; independent valuation by mid office.','investments'],
 ['TR-14','Stale valuation','Investment Portfolio - Valuation','RBI','RBI Investment Portfolio Directions, 2023 (HFT valued daily; AFS / FVTPL at each reporting date)','SA 540 (Revised); SA 500 Audit Evidence','Medium','Revalue securities as at the reporting date using FBIL / exchange prices.','investments'],
 ['TR-15','Non-SLR investment below investment grade / unrated','Investment Portfolio - Non-SLR','RBI','RBI Investment Portfolio Directions, 2023 - non-SLR investments (unrated / unlisted ceilings, credit appraisal)','SA 250; SA 540 (Revised)','Medium','Obtain credit appraisal and Board approval; monitor the unrated / unlisted ceiling; assess impairment.','investments'],
 ['TR-16','Capital market exposure ceiling breach','Exposure Norms - Capital Market','RBI','RBI Master Circular - Exposure Norms (capital market exposure ceiling linked to net worth)','SA 250; SA 330','High','Bring exposure within the ceiling; report to the Board; add a CME check to pre-deal limits.','positions'],
 ['TR-17','Trade in scrip on restricted (insider) list','Capital Markets - Insider Trading','SEBI','SEBI (Prohibition of Insider Trading) Regulations, 2015 - Code of Conduct, restricted list, Chinese walls (Reg 9, Schedule B)','SA 250; SA 240 Fraud','High','Block restricted scrips in the order management system; investigate and report to the Compliance Officer and Audit Committee.','deals'],
 ['TR-18','Derivative with user without suitability / ISDA','Derivatives - User Suitability','RBI','RBI (Market-makers in OTC Derivatives) Directions, 2021 - user classification, suitability and appropriateness; ISDA / CSA documentation','SA 250; SA 315 (Revised)','High','Complete suitability assessment and execute ISDA / CSA before dealing; review all user derivatives.','deals'],
 ['TR-19','IBU transaction in INR','IFSC Banking Unit - Currency','IFSCA','IFSCA (Banking) Regulations, 2020 - IBU to transact in specified foreign currencies; FEMA 1999','SA 250; SA 330','High','Reverse / regularise the INR transaction; configure the IBU book to block INR deals.','deals'],
 ['TR-20','IBU ring-fencing breach','IFSC Banking Unit - Ring-fencing','IFSCA','IFSCA (Banking) Regulations, 2020 - separate books and ring-fencing of IBU from domestic operations','SA 315 (Revised); SA 265','High','Rebook the deal in the correct book; enforce book-level segregation and separate dealer IDs for IBU.','deals'],
 ['TR-21','IBU dealing with resident individual','IFSC Banking Unit - Permissible Persons','IFSCA / FEMA','IFSCA Banking Regulations / Handbook - dealings with resident individuals only as permitted (e.g. under LRS); FEMA 1999','SA 250','Medium','Verify permissibility and LRS documentation; obtain Compliance sign-off.','deals'],
 ['TR-22','Counterparty KYC pending','KYC / AML','RBI','RBI Master Direction - Know Your Customer (KYC) Direction, 2016; PMLA 2002','SA 250; SA 240','Medium','Stop fresh deals until KYC is complete; review AML monitoring for the counterparty.','counterparties'],
 ['TR-23','Holdings not reconciled with depository / SGL','Custody and Reconciliation','SEBI / RBI','SEBI (Depositories and Participants) Regulations, 2018 (demat holdings); RBI SGL / CSGL reconciliation','SA 505 External Confirmations; SA 500 Audit Evidence','High','Reconcile holdings with NSDL / CDSL / SGL statements; investigate and rectify differences.','investments']
];
const TM = {};
CAT.forEach(function (c) { TM[c[0]] = { id: c[0], name: c[1], area: c[2], regulator: c[3], ref: c[4], icai: c[5], risk: c[6], rec: c[7], pop: c[8] }; });

const findings = [];
const add = function (tid, entity, obs, impact, riskOverride, regOverride) {
  const t = TM[tid];
  findings.push({ test_id: tid, test_name: t.name, area: t.area, regulator: regOverride || t.regulator, regulation_ref: t.ref, icai_standard: t.icai, risk: riskOverride || t.risk, ref_entity: entity, observation: obs, impact_inr_cr: r2(impact || 0), recommendation: t.rec });
};
const cr = function (x) { return 'Rs ' + r2(num(x)) + ' cr'; };

deals.forEach(function (d) {
  const n = num(d.notional_inr_cr);
  const label = d.deal_id + ' (' + d.instrument + ', ' + cr(n) + ', ' + d.counterparty + ')';
  if (d.confirmation_status !== 'Matched') add('TR-01', d.deal_id, 'Deal ' + label + ' is ' + String(d.confirmation_status || 'blank').toUpperCase() + ' - no matched counterparty confirmation on record.', n);
  if (d.confirmation_date && d.confirmation_time) {
    const delay = (ts(d.confirmation_date, d.confirmation_time) - ts(d.trade_date, d.trade_time)) / 3600000;
    if (delay > num(P.confirmation_sla_hours || 2)) add('TR-02', d.deal_id, 'Deal ' + label + ' confirmed ' + r2(delay) + ' hours after trade, against SLA of ' + P.confirmation_sla_hours + ' hours.', n);
  }
  const conf = dlMap[d.confirmed_by];
  if (d.confirmed_by && (d.confirmed_by === d.dealer_id || (conf && conf.role === 'Front'))) add('TR-03', d.deal_id, 'Deal ' + label + ' was executed by dealer ' + d.dealer_id + ' and confirmed by ' + d.confirmed_by + ' (same person / front office).', n);
  const dr = num(d.deal_rate); const mr = num(d.market_rate);
  if (mr) {
    if (d.rate_type === 'yield') {
      const bps = Math.abs(dr - mr) * 100;
      if (bps > num(P.rate_tolerance_bps || 10)) add('TR-04', d.deal_id, 'Deal ' + label + ' done at ' + dr + '% vs market ' + mr + '% - deviation ' + r2(bps) + ' bps (tolerance ' + P.rate_tolerance_bps + ' bps).', n * bps / 10000);
    } else {
      const pct = Math.abs(dr - mr) / mr * 100;
      if (pct > num(P.price_tolerance_pct || 0.25)) add('TR-04', d.deal_id, 'Deal ' + label + ' done at ' + dr + ' vs market ' + mr + ' - deviation ' + r2(pct) + '% (tolerance ' + P.price_tolerance_pct + '%).', n * pct / 100);
    }
  }
  const m = hm(d.trade_time);
  if (m !== null && (m < hm(P.dealing_start || '09:00') || m > hm(P.dealing_end || '17:30')) && d.after_hours_approval !== 'Y') add('TR-05', d.deal_id, 'Deal ' + label + ' executed at ' + d.trade_time + ', outside dealing hours ' + P.dealing_start + '-' + P.dealing_end + ', without prior approval.', n);
  if (d.recorded_line === 'N') add('TR-05', d.deal_id, 'Deal ' + label + ' was not executed on a recorded line / electronic platform.', n);
  const dl = dlMap[d.dealer_id];
  if (dl && num(dl.per_deal_limit_cr) > 0 && n > num(dl.per_deal_limit_cr)) add('TR-07', d.deal_id, 'Deal ' + label + ' by ' + dl.name + ' (' + d.dealer_id + ') exceeds per-deal limit of ' + cr(dl.per_deal_limit_cr) + ' by ' + cr(n - num(dl.per_deal_limit_cr)) + '.', n - num(dl.per_deal_limit_cr));
  if (d.settlement_status === 'Failed' || d.sgl_bounce === 'Y') add('TR-11', d.deal_id, 'Deal ' + label + ' failed in settlement' + (d.sgl_bounce === 'Y' ? ' (SGL bounce).' : '.'), n);
  if (d.desk === 'Equity' && d.isin) {
    const hit = rl.filter(function (r) { return r.isin === d.isin && String(d.trade_date) >= String(r.restricted_from) && String(d.trade_date) <= String(r.restricted_to); })[0];
    if (hit) add('TR-17', d.deal_id, 'Deal ' + label + ' on ' + d.trade_date + ' in ' + hit.scrip + ', which was on the restricted list from ' + hit.restricted_from + ' to ' + hit.restricted_to + ' (' + hit.reason + ').', n);
  }
  const cp = cpMap[d.counterparty] || {};
  if (d.desk === 'Derivatives' && String(cp.type || '').indexOf('Corporate') === 0 && (d.isda_csa !== 'Y' || d.suitability_done !== 'Y')) add('TR-18', d.deal_id, 'Derivative ' + label + ' with user ' + d.counterparty + ' - ISDA/CSA: ' + d.isda_csa + ', suitability assessment: ' + d.suitability_done + '.', n);
  if (d.book === 'IBU' && d.currency === 'INR') add('TR-19', d.deal_id, 'IBU deal ' + label + ' is denominated in INR.', n);
  if ((d.desk === 'IBU') !== (d.book === 'IBU')) add('TR-20', d.deal_id, 'Deal ' + label + ' executed by the ' + d.desk + ' desk but booked in the ' + d.book + ' book.', n);
  if (d.book === 'IBU' && cp.type === 'Resident Individual') add('TR-21', d.deal_id, 'IBU deal ' + label + ' with a resident individual - permissibility and LRS documentation to be verified.', n);
});

const expo = {};
deals.forEach(function (d) { expo[d.counterparty] = (expo[d.counterparty] || 0) + num(d.notional_inr_cr); });
Object.keys(expo).forEach(function (k) {
  const c = cpMap[k];
  if (c && expo[k] > num(c.limit_cr)) add('TR-06', k, 'Aggregate exposure on ' + k + ' of ' + cr(expo[k]) + ' exceeds approved limit of ' + cr(c.limit_cr) + ' by ' + cr(expo[k] - num(c.limit_cr)) + '.', expo[k] - num(c.limit_cr));
  if (c && c.kyc_status !== 'Complete') add('TR-22', k, 'Deals of ' + cr(expo[k]) + ' done with ' + k + ' while KYC status is ' + c.kyc_status + '.', expo[k]);
});

dealers.forEach(function (d) {
  const loss = -num(d.period_pnl_lakh);
  if (d.role === 'Front' && num(d.stop_loss_lakh) > 0 && loss > num(d.stop_loss_lakh)) add('TR-08', d.dealer_id, 'Dealer ' + d.name + ' (' + d.desk + ') period loss of Rs ' + loss + ' lakh breached stop-loss of Rs ' + d.stop_loss_lakh + ' lakh.', loss / 100);
});

const cap = num(P.capital_funds_cr); const nw = num(P.net_worth_cr);
pos.forEach(function (p) {
  if (num(p.noop_usd_mn) > num(P.noop_limit_usd_mn)) add('TR-09', p.date, 'NOOP on ' + p.date + ' was USD ' + p.noop_usd_mn + ' mn against limit of USD ' + P.noop_limit_usd_mn + ' mn.', (num(p.noop_usd_mn) - num(P.noop_limit_usd_mn)) * 8.4 / 10);
  const bl = cap * num(P.call_borrow_limit_pct) / 100; const ll = cap * num(P.call_lend_limit_pct) / 100;
  if (num(p.call_borrow_cr) > bl) add('TR-10', p.date, 'Call borrowing on ' + p.date + ' of ' + cr(p.call_borrow_cr) + ' exceeded ' + P.call_borrow_limit_pct + '% of capital funds (' + cr(bl) + ').', num(p.call_borrow_cr) - bl);
  if (num(p.call_lend_cr) > ll) add('TR-10', p.date, 'Call lending on ' + p.date + ' of ' + cr(p.call_lend_cr) + ' exceeded ' + P.call_lend_limit_pct + '% of capital funds (' + cr(ll) + ').', num(p.call_lend_cr) - ll);
  const cl = nw * num(P.cme_limit_pct) / 100;
  if (num(p.cme_cr) > cl) add('TR-16', p.date, 'Capital market exposure on ' + p.date + ' of ' + cr(p.cme_cr) + ' exceeded ' + P.cme_limit_pct + '% of net worth (' + cr(cl) + ').', num(p.cme_cr) - cl);
});

const IG = ['SOV','AAA','AA+','AA','AA-','A+','A','A-','BBB+','BBB','BBB-'];
let htmSold = 0;
inv.forEach(function (s) {
  const bv = num(s.book_value_cr); const mv = num(s.market_value_cr);
  const label = s.security + ' (' + s.isin + ', ' + s.category + ')';
  if (s.category === 'HTM' && s.sold_in_period === 'Y') {
    htmSold += num(s.sale_book_value_cr);
    if (!s.board_approval_ref) add('TR-12', s.isin, 'Sale of ' + cr(s.sale_book_value_cr) + ' of ' + label + ' from HTM without Board approval reference.', num(s.sale_book_value_cr));
  }
  if (s.category !== 'HTM') {
    const loss = bv - mv;
    if (loss > 0) {
      const provided = Math.max(0, -num(s.mtm_booked_cr));
      const short = loss - provided;
      if (short > 0.01) add('TR-13', s.isin, label + ': fair value loss ' + cr(loss) + ', recognised only ' + cr(provided) + ' - shortfall ' + cr(short) + '.', short, short >= mat ? 'High' : 'Medium');
    }
    if (s.valuation_date && periodTo && String(s.valuation_date) < periodTo) add('TR-14', s.isin, label + ' last valued on ' + s.valuation_date + ', not as at period end ' + periodTo + '.', bv);
  }
  if (s.slr !== 'Y' && (s.issuer_type === 'Corporate' || s.issuer_type === 'Bank') && IG.indexOf(String(s.rating)) < 0) add('TR-15', s.isin, label + ' is rated ' + s.rating + (s.listed === 'N' ? ' and unlisted' : '') + ' - below investment grade / unrated non-SLR exposure of ' + cr(bv) + '.', bv);
  if (num(s.holding_units) !== num(s.depository_units)) add('TR-23', s.isin, label + ': books show ' + s.holding_units + ' units, ' + s.custodian + ' statement shows ' + s.depository_units + ' units (difference ' + (num(s.holding_units) - num(s.depository_units)) + ').', bv * Math.abs(num(s.holding_units) - num(s.depository_units)) / Math.max(1, num(s.holding_units)), null, (s.custodian === 'NSDL' || s.custodian === 'CDSL') ? 'SEBI' : 'RBI');
});
const htmOpen = num(P.htm_opening_book_cr);
if (htmOpen > 0) {
  const pct = htmSold / htmOpen * 100;
  if (pct > num(P.htm_sale_threshold_pct)) add('TR-12', 'HTM portfolio', 'HTM sales during the period of ' + cr(htmSold) + ' = ' + r2(pct) + '% of opening HTM book (' + cr(htmOpen) + '), above the ' + P.htm_sale_threshold_pct + '% threshold - disclosure in Notes to Accounts required.', htmSold, 'Medium');
}

const now = $now.setZone('Asia/Kolkata');
const runId = 'TA-' + now.toFormat('yyyyMMdd-HHmmss');
findings.forEach(function (f, i) { f.finding_id = runId + '-' + String(i + 1).padStart(2, '0'); f.run_id = runId; f.status = 'Open'; f.management_response = ''; f.action_owner = ''; f.target_date = ''; f.created_at = now.toFormat('yyyy-MM-dd HH:mm'); });

const popCount = { deals: deals.length, investments: inv.length, counterparties: cps.length, dealers: dealers.length, positions: pos.length };
const tests = CAT.map(function (c) {
  const t = TM[c[0]];
  const ex = findings.filter(function (f) { return f.test_id === t.id; });
  return { id: t.id, name: t.name, area: t.area, regulator: t.regulator, reference: t.ref, icai: t.icai, population: popCount[t.pop] || 0, population_type: t.pop, exceptions: ex.length, status: ex.length ? 'Exceptions' : 'No exceptions' };
});
const fw = ['RBI','SEBI','IFSCA','FEMA'];
const compliance = fw.map(function (k) {
  const ts2 = tests.filter(function (t) { return t.regulator.indexOf(k) >= 0; });
  const fs = findings.filter(function (f) { return f.regulator.indexOf(k) >= 0; });
  const hi = fs.filter(function (f) { return f.risk === 'High'; }).length;
  return { framework: k, tests: ts2.length, exceptions: fs.length, high: hi, status: fs.length === 0 ? 'Compliant' : (hi > 0 ? 'Non-compliant - High risk' : 'Partially compliant') };
});
const saSet = {};
['SA 200','SA 230','SA 265','SA 315 (Revised)','SA 320','SA 330','SA 500','SA 530','SA 580'].forEach(function (s) { saSet[s] = 1; });
tests.forEach(function (t) { t.icai.split(';').forEach(function (s) { const m2 = s.trim().match(/^SA [0-9]+( [(]Revised[)])?/); if (m2) saSet[m2[0]] = 1; }); });
const icaiApplied = Object.keys(saSet).sort();
compliance.push({ framework: 'ICAI Standards', tests: icaiApplied.length, exceptions: 0, high: 0, status: 'Applied: ' + icaiApplied.join(', ') });

const high = findings.filter(function (f) { return f.risk === 'High'; }).length;
const med = findings.filter(function (f) { return f.risk === 'Medium'; }).length;
const low = findings.filter(function (f) { return f.risk === 'Low'; }).length;
const overall = high >= 8 ? 'High Risk - Unsatisfactory' : (high >= 3 ? 'Medium Risk - Needs Improvement' : 'Low Risk - Satisfactory');
const totalNotional = deals.reduce(function (a, d) { return a + num(d.notional_inr_cr); }, 0);
const atRisk = findings.reduce(function (a, f) { return a + num(f.impact_inr_cr); }, 0);
const sample = deals.slice().sort(function (a, b) { return num(b.notional_inr_cr) - num(a.notional_inr_cr); }).slice(0, 5).map(function (d) { return { deal_id: d.deal_id, instrument: d.instrument, counterparty: d.counterparty, notional_inr_cr: num(d.notional_inr_cr), reason: 'Top value - vouch to deal ticket, voice log, CCIL / SWIFT confirmation and accounting entry' }; });
const fingerprint = 'D' + deals.length + '-I' + inv.length + '-C' + cps.length + '-L' + dealers.length + '-P' + pos.length + '-N' + r2(totalNotional);
const stats = { tests_run: tests.length, tests_with_exceptions: tests.filter(function (t) { return t.exceptions > 0; }).length, findings: findings.length, high: high, medium: med, low: low, deals: deals.length, investments: inv.length, total_notional_cr: r2(totalNotional), amount_flagged_cr: r2(atRisk) };
const brief = {
  bank: P.bank_name, period: P.audit_period_from + ' to ' + P.audit_period_to, engagement: req.engagement, auditor: req.auditor_name, run_id: runId,
  overall_rating: overall, materiality_cr: mat, stats: stats,
  compliance: compliance, icai_standards_applied: icaiApplied,
  tests: tests.map(function (t) { return { id: t.id, name: t.name, regulator: t.regulator, reference: t.reference, icai: t.icai, population: t.population, exceptions: t.exceptions }; }),
  findings: findings.map(function (f) { return { id: f.finding_id, test: f.test_id, risk: f.risk, regulator: f.regulator, entity: f.ref_entity, observation: f.observation, impact_cr: f.impact_inr_cr }; }),
  walkthrough_sample: sample
};
return [{ json: { run_id: runId, run_at: now.toFormat('yyyy-MM-dd HH:mm:ss'), bank_name: P.bank_name, period: P.audit_period_from + ' to ' + P.audit_period_to, engagement: req.engagement, auditor_name: req.auditor_name, auditor_email: req.auditor_email || P.default_auditor_email || '', trigger_source: req.trigger_source, overall_rating: overall, materiality_cr: mat, stats: stats, tests: tests, findings: findings, compliance: compliance, icai_standards: icaiApplied, sample: sample, data_fingerprint: fingerprint, ai_brief: JSON.stringify(brief) } }];

values.content:
=Prepare the treasury audit report for the engagement below. Use ONLY the facts in the JSON; do not invent numbers, deals or regulations. Keep the whole report under 1,100 words and finish every section - the detailed findings register is appended separately as Annexure A, so summarise rather than list every exception.

AUDIT DATA (JSON):
{{ $json.ai_brief }}

parameters.jsCode:
const E = $('Run Audit Tests').first().json;
const a = $input.first().json || {};
let text = '';
if (Array.isArray(a.content)) { const b = a.content.filter(function (c) { return c && c.type === 'text'; }).map(function (c) { return c.text; }); text = b.join(String.fromCharCode(10)); }
else if (typeof a.merged_response === 'string') text = a.merged_response;
else if (typeof a.content === 'string') text = a.content;
else if (typeof a.text === 'string') text = a.text;
const fence = String.fromCharCode(96, 96, 96);
